namespace lc0019 {
class Solution {
 public:
  ListNode* removeNthFromEnd(ListNode* head, int n) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* fast = &dummy;
    for (int i = 0; i < n; ++i) fast = fast->next;  // 先走 n 步
    ListNode* slow = &dummy;
    while (fast->next) {
      slow = slow->next;
      fast = fast->next;
    }
    ListNode* victim = slow->next;
    slow->next = victim->next;
    delete victim;  // 题目语义是删除，测试里就不能让它泄漏
    return dummy.next;
  }
};
}

