namespace lc0020 {
class Solution {
 public:
  bool isValid(const string& s) {
    stack<char> st;
    for (char c : s) {
      if (c == '(' || c == '[' || c == '{') {
        st.push(c);
      } else {
        if (st.empty()) return false;  // 右括号多余
        char open = st.top();
        st.pop();
        if (c == ')' && open != '(') return false;
        if (c == ']' && open != '[') return false;
        if (c == '}' && open != '{') return false;
      }
    }
    return st.empty();  // 左括号不能剩余
  }
};
}

