CHECK_TRUE(s.isValid("{[]}"));
CHECK_FALSE(s.isValid("]"));   // 以右括号开头
CHECK_FALSE(s.isValid("("));   // 结束时栈非空
CHECK_TRUE(s.isValid(""));

