namespace lc0024 {
class Solution {
 public:
  ListNode* swapPairs(ListNode* head) {
    ListNode dummy(0);
    dummy.next = head;
    ListNode* prev = &dummy;
    while (prev->next && prev->next->next) {
      ListNode* first = prev->next;
      ListNode* second = first->next;
      first->next = second->next;
      second->next = first;
      prev->next = second;
      prev = first;  // 交换后 first 已是本组尾部
    }
    return dummy.next;
  }
};
}

