namespace lc0033 {
class Solution {
 public:
  int search(vector<int>& nums, int target) {
    int lo = 0, hi = (int)nums.size() - 1;
    while (lo <= hi) {
      int mid = lo + (hi - lo) / 2;
      if (nums[mid] == target) return mid;
      if (nums[lo] <= nums[mid]) {  // 左半 [lo, mid] 有序
        if (nums[lo] <= target && target < nums[mid])
          hi = mid - 1;
        else
          lo = mid + 1;
      } else {                      // 右半 [mid, hi] 有序
        if (nums[mid] < target && target <= nums[hi])
          lo = mid + 1;
        else
          hi = mid - 1;
      }
    }
    return -1;
  }
};
}

