namespace lc0041 {
class Solution {
 public:
  int firstMissingPositive(vector<int>& nums) {
    const int n = (int)nums.size();
    for (int& x : nums)
      if (x <= 0) x = n + 1;  // 非正数不可能参与标记，换成哨兵
    for (int i = 0; i < n; ++i) {
      int x = std::abs(nums[i]);
      if (x <= n) nums[x - 1] = -std::abs(nums[x - 1]);  // 标记 x 出现过
    }
    for (int i = 0; i < n; ++i)
      if (nums[i] > 0) return i + 1;
    return n + 1;
  }
};
}

