namespace lc0045 {
class Solution {
 public:
  int jump(vector<int>& nums) {
    const int n = (int)nums.size();
    int steps = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i < n - 1; ++i) {  // 不处理最后一个元素
      farthest = max(farthest, i + nums[i]);
      if (i == curEnd) {  // 到边界了，必须跳
        ++steps;
        curEnd = farthest;
        if (curEnd >= n - 1) break;
      }
    }
    return steps;
  }
};
}

