namespace lc0053 {
class Solution {
 public:
  int maxSubArray(vector<int>& nums) {
    if (nums.empty()) return 0;  // 力扣保证 n ≥ 1，这里只是不让本地调用碰到 nums[0] 越界
    int f = nums[0], ans = nums[0];
    for (size_t i = 1; i < nums.size(); ++i) {
      f = max(f + nums[i], nums[i]);
      ans = max(ans, f);
    }
    return ans;
  }
};
}

