namespace lc0055 {
class Solution {
 public:
  bool canJump(vector<int>& nums) {
    int reach = 0;
    for (int i = 0; i < (int)nums.size(); ++i) {
      if (i > reach) return false;  // 当前位置不可达
      reach = max(reach, i + nums[i]);
      if (reach >= (int)nums.size() - 1) return true;  // 提前收工
    }
    return true;
  }
};
}

