namespace lc0075 {
class Solution {
 public:
  void sortColors(vector<int>& nums) {
    int p0 = 0, i = 0, p2 = (int)nums.size() - 1;
    while (i <= p2) {
      if (nums[i] == 0) {
        swap(nums[i++], nums[p0++]);  // 换回的是 1（或自己），可以放心前进
      } else if (nums[i] == 2) {
        swap(nums[i], nums[p2--]);    // 换回来的还没看过，i 不动，下一轮再看
      } else {
        ++i;  // 1 就在正确区域
      }
    }
  }
};
}

