namespace lc0102 {
class Solution {
 public:
  vector<vector<int>> levelOrder(TreeNode* root) {
    vector<vector<int>> ans;
    if (!root) return ans;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
      int sz = (int)q.size();  // 本层结点数，关键一步
      ans.emplace_back();
      ans.back().reserve(sz);
      for (int i = 0; i < sz; ++i) {
        TreeNode* cur = q.front();
        q.pop();
        ans.back().push_back(cur->val);
        if (cur->left) q.push(cur->left);
        if (cur->right) q.push(cur->right);
      }
    }
    return ans;
  }
};
}

