namespace lc0121 {
class Solution {
 public:
  int maxProfit(vector<int>& prices) {
    if (prices.empty()) return 0;  // 防 prices[0] 越界（题面保证 n >= 1）
    int ans = 0;
    int low = prices[0];  // 到目前为止的最低买入价
    for (int p : prices) {
      ans = max(ans, p - low);  // 今天卖
      low = min(low, p);        // 更新「今天及之前」最便宜的买点
    }
    return ans;  // 全程下跌时保持 0（不交易）
  }
};
}

