namespace lc0124 {
class Solution {
 public:
  int maxPathSum(TreeNode* root) {
    int best = INT_MIN;
    gain(root, best);
    return best;
  }

 private:
  static int gain(TreeNode* n, int& best) {
    if (!n) return 0;
    int l = max(0, gain(n->left, best));   // 负收益的子树直接不要
    int r = max(0, gain(n->right, best));
    best = max(best, l + r + n->val);      // 在 n 处拐弯的完整路径
    return n->val + max(l, r);             // 只能带一条边上传
  }
};
}

