namespace lc0128 {
class Solution {
 public:
  int longestConsecutive(vector<int>& nums) {
    unordered_set<int> pool(nums.begin(), nums.end());  // 顺便去重
    int best = 0;
    for (int x : pool) {
      if (pool.count(x - 1)) continue;  // 不是起点，跳过
      int cur = x, len = 0;
      while (pool.count(cur)) {
        ++len;
        ++cur;  // 向右延伸
      }
      best = max(best, len);
    }
    return best;
  }
};
}

