namespace lc0142 {
class Solution {
 public:
  ListNode* detectCycle(ListNode* head) {
    ListNode *slow = head, *fast = head;
    while (fast && fast->next) {
      slow = slow->next;
      fast = fast->next->next;
      if (slow == fast) {           // 相遇，开始在环里「对表」
        slow = head;
        while (slow != fast) {
          slow = slow->next;
          fast = fast->next;        // 这一步两人都走 1 步
        }
        return slow;                // 两指针同步停在入口；无环的情况由下面的 return nullptr 处理
      }
    }
    return nullptr;
  }
};
}

