namespace lc0155 {
class MinStack {
 public:
  void push(int val) {
    st_.push(val);
    // 关键：压的是「val 与当前最小值里的较小者」，min_ 栈顶永远是 st_ 全体的最小值
    min_.push(min_.empty() ? val : min(val, min_.top()));
  }

  void pop() {
    st_.pop();
    min_.pop();
  }

  int top() const { return st_.top(); }
  int getMin() const { return min_.top(); }

 private:
  stack<int> st_;
  stack<int> min_;
};
}

