namespace lc0199 {
class Solution {
 public:
  vector<int> rightSideView(TreeNode* root) {
    vector<int> ans;
    if (!root) return ans;
    queue<TreeNode*> q{{root}};
    while (!q.empty()) {
      int sz = (int)q.size();
      for (int i = 0; i < sz; ++i) {
        TreeNode* cur = q.front();
        q.pop();
        if (i == sz - 1) ans.push_back(cur->val);  // 本层最右
        if (cur->left) q.push(cur->left);
        if (cur->right) q.push(cur->right);
      }
    }
    return ans;
  }
};
}

