namespace lc0200 {
class Solution {
 public:
  int numIslands(vector<vector<char>>& grid) {
    int ans = 0;
    for (int i = 0; i < (int)grid.size(); ++i)
      for (int j = 0; j < (int)grid[0].size(); ++j)
        if (grid[i][j] == '1') {
          ++ans;
          sink(grid, i, j);
        }
    return ans;
  }

 private:
  static void sink(vector<vector<char>>& g, int i, int j) {
    if (i < 0 || j < 0 || i >= (int)g.size() || j >= (int)g[0].size() || g[i][j] != '1') return;
    g[i][j] = '0';  // 先标记再展开，防止来回递归
    sink(g, i + 1, j);
    sink(g, i - 1, j);
    sink(g, i, j + 1);
    sink(g, i, j - 1);
  }
};
}

namespace lc0206 {
class Solution {
 public:
  static ListNode* reverseIterative(ListNode* head) {
    ListNode* prev = nullptr;
    while (head) {
      ListNode* nxt = head->next;  // 先存，否则改链后丢失后继
      head->next = prev;
      prev = head;
      head = nxt;
    }
    return prev;
  }

  static ListNode* reverseRecursive(ListNode* head) {
    if (!head || !head->next) return head;
    ListNode* newHead = reverseRecursive(head->next);
    head->next->next = head;  // 让后继指回自己
    head->next = nullptr;     // 断开原来的正向边（临时尾结点）
    return newHead;
  }
};
}

