namespace lc0208 {
class Trie {
 public:
  Trie() = default;
  ~Trie() {
    for (Trie* c : kids_) delete c;
  }
  Trie(const Trie&) = delete;
  Trie& operator=(const Trie&) = delete;

  void insert(const string& word) {
    Trie* cur = this;
    for (char ch : word) {
      int i = ch - 'a';
      if (!cur->kids_[i]) cur->kids_[i] = new Trie();
      cur = cur->kids_[i];
    }
    cur->isEnd_ = true;
  }

  bool search(const string& word) const {
    const Trie* n = walk(word);
    return n && n->isEnd_;
  }

  bool startsWith(const string& prefix) const { return walk(prefix) != nullptr; }

 private:
  std::array<Trie*, 26> kids_{};  // {} -> 全部初始化为 nullptr
  bool isEnd_ = false;

  Trie* walk(const string& s) {
    Trie* cur = this;
    for (char ch : s) {
      int i = ch - 'a';
      if (!cur->kids_[i]) return nullptr;
      cur = cur->kids_[i];
    }
    return cur;
  }
  const Trie* walk(const string& s) const {
    const Trie* cur = this;
    for (char ch : s) {
      int i = ch - 'a';
      if (!cur->kids_[i]) return nullptr;
      cur = cur->kids_[i];
    }
    return cur;
  }
};
}

