namespace lc0230 {
class Solution {
 public:
  int kthSmallest(TreeNode* root, int k) {
    stack<TreeNode*> st;
    TreeNode* cur = root;
    while (cur || !st.empty()) {
      while (cur) {
        st.push(cur);
        cur = cur->left;
      }
      cur = st.top();
      st.pop();
      if (--k == 0) return cur->val;  // 第 k 个被访问的结点
      cur = cur->right;
    }
    return -1;  // 题目保证 k 合法
  }
};
}

