namespace lc0238 {
class Solution {
 public:
  vector<int> productExceptSelf(vector<int>& nums) {
    const int n = (int)nums.size();
    vector<int> ans(n, 1);
    int left = 1;
    for (int i = 0; i < n; ++i) {
      ans[i] = left;  // i 左边所有数的积
      left *= nums[i];
    }
    int right = 1;
    for (int i = n - 1; i >= 0; --i) {
      ans[i] *= right;  // 乘上 i 右边所有数的积
      right *= nums[i];
    }
    return ans;
  }
};
}

