namespace lc0322 {
class Solution {
 public:
  int coinChange(vector<int>& coins, int amount) {
    const int BIG = amount + 1;  // 比任何合法解都大，等价于无穷
    vector<int> dp(amount + 1, BIG);
    dp[0] = 0;
    for (int a = 1; a <= amount; ++a)
      for (int c : coins)
        if (c <= a) dp[a] = min(dp[a], dp[a - c] + 1);
    return dp[amount] == BIG ? -1 : dp[amount];
  }
};
}

