namespace lc0394 {
class Solution {
 public:
  string decodeString(const string& s) {
    stack<int> nums;
    stack<string> parts;
    string cur;
    int num = 0;
    for (char c : s) {
      if (isdigit((unsigned char)c)) {
        num = num * 10 + (c - '0');
      } else if (c == '[') {
        nums.push(num);   // 本层要重复几次
        parts.push(cur);  // 保存本层之前的内容
        num = 0;
        cur.clear();      // 开始收集本层内容
      } else if (c == ']') {
        string body = cur;
        int times = nums.top();
        nums.pop();
        cur = parts.top();  // 回到上一层
        parts.pop();
        for (int i = 0; i < times; ++i) cur += body;
      } else {
        cur += c;
      }
    }
    return cur;
  }
};
}

