namespace lc0543 {
class Solution {
 public:
  int diameterOfBinaryTree(TreeNode* root) {
    int best = 0;
    height(root, best);
    return best;
  }

 private:
  static int height(TreeNode* n, int& best) {
    if (!n) return 0;
    int l = height(n->left, best);
    int r = height(n->right, best);
    best = max(best, l + r);  // 经过 n 的最长路径（边数）
    return 1 + max(l, r);
  }
};
}

