namespace lc0763 {
class Solution {
 public:
  vector<int> partitionLabels(const string& s) {
    vector<int> last(26, -1);
    for (int i = 0; i < (int)s.size(); ++i) last[s[i] - 'a'] = i;
    vector<int> ans;
    int start = 0, end = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
      end = max(end, last[s[i] - 'a']);  // 想把这段留在身后，就得至少延伸到 end
      if (i == end) {
        ans.push_back(i - start + 1);
        start = i + 1;
      }
    }
    return ans;
  }
};
}

