namespace lc01143 {
class Solution {
 public:
  int longestCommonSubsequence(const string& a, const string& b) {
    const int m = (int)a.size(), n = (int)b.size();
    vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));  // 空串那一行/列是天然边界
    for (int i = 1; i <= m; ++i)
      for (int j = 1; j <= n; ++j)
        dp[i][j] = (a[i - 1] == b[j - 1]) ? dp[i - 1][j - 1] + 1
                                          : max(dp[i - 1][j], dp[i][j - 1]);
    return dp[m][n];
  }
};
}
